<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ArrowLeft, ChevronDown, ChevronRight, File, FileImage, FilePlus2, FileText, Folder, FolderOpen, GitBranch, Grid2X2, History, List, LoaderCircle, PanelLeftClose, RefreshCw, Search, Table2, Upload } from 'lucide-vue-next';
import type { BranchItem, CommitItem, FileTreeNode } from '@oxen/shared';
import { queryString, request } from '../api';
import FileTree from './FileTree.vue';
import FilePreview from './FilePreview.vue';
const props=defineProps<{base:string;branch:string}>();
const route=useRoute(),router=useRouter();
const path=ref(String(route.query.path??'')),selected=ref(String(route.query.file??'')),nodes=ref<FileTreeNode[]>([]),loading=ref(true),error=ref(''),commitError=ref(''),search=ref(''),associated=ref(''),treeVisible=ref(false),layout=ref<'list'|'grid'>('list'),sort=ref('name'),snapshotRef=ref(''),latestCommit=ref<CommitItem>(),fileMenu=ref<HTMLDetailsElement|null>(null);let generation=0;
const breadcrumbs=computed(()=>path.value.split('/').filter(Boolean).map((name,i,all)=>({name,path:all.slice(0,i+1).join('/')})));
const filtered=computed(()=>nodes.value.filter(n=>n.name.toLowerCase().includes(search.value.toLowerCase())).sort((a,b)=>{if(a.kind!==b.kind)return a.kind==='directory'?-1:1;if(sort.value==='updated')return (Date.parse(b.updatedAt??'')||0)-(Date.parse(a.updatedAt??'')||0);if(sort.value==='size')return b.size-a.size;return a.name.localeCompare(b.name,'zh-CN');}));
const repoPath=computed(()=>`/repos/${encodeURIComponent(String(route.params.namespace))}/${encodeURIComponent(String(route.params.repo))}`);
const historyLink=computed(()=>({path:repoPath.value+'/commits',query:{branch:props.branch}}));
const commitLink=computed(()=>({path:repoPath.value+'/commits',query:{branch:props.branch,...(latestCommit.value?{commit:latestCommit.value.id}:{})}}));
function workspaceLink(action:string){return {path:repoPath.value+'/workspaces',query:{branch:props.branch,...(path.value?{path:path.value}:{}),action}};}
function bytes(n:number){if(!n)return '—';if(n<1024)return n+' B';if(n<1024**2)return (n/1024).toFixed(1)+' KB';return (n/1024**2).toFixed(1)+' MB';}
function date(value?:string){return value?new Date(value).toLocaleDateString('zh-CN',{year:'numeric',month:'short',day:'numeric'}):'—';}
function icon(node:FileTreeNode){if(node.kind==='directory')return Folder;return /csv|parquet|jsonl|ndjson|tsv/.test(node.extension)?Table2:/png|jpg|jpeg|webp|svg/.test(node.extension)?FileImage:/md|txt|json/.test(node.extension)?FileText:File;}
async function load(){const current=++generation;loading.value=true;error.value='';commitError.value='';try{const branches=await request<BranchItem[]>(props.base+'/branches');if(current!==generation)return;const reference=branches.find(item=>item.name===props.branch)?.commitId??props.branch;const [files,commits]=await Promise.all([request<FileTreeNode[]>(props.base+'/tree'+queryString({ref:reference,path:path.value})),request<CommitItem[]>(props.base+'/commits'+queryString({ref:reference,page:1,pageSize:1})).catch(cause=>{if(current===generation)commitError.value=(cause as Error).message;return [] as CommitItem[];})]);if(current===generation){nodes.value=files;snapshotRef.value=reference;latestCommit.value=commits[0];}}catch(e){if(current===generation)error.value=(e as Error).message;}finally{if(current===generation)loading.value=false;}}
async function directory(value:string){await router.replace({query:{branch:props.branch,...(value?{path:value}:{})}});if(String(route.query.path??'')===value&&!route.query.file)search.value='';}
function select(node:FileTreeNode){if(node.kind==='directory')void directory(node.path);else void router.replace({query:{branch:props.branch,path:path.value,file:node.path}});}
function closePreview(){const query={...route.query};delete query.file;delete query.row;delete query.page;void router.replace({query});}
watch(()=>[route.query.path,route.query.file],()=>{const nextPath=String(route.query.path??'');selected.value=String(route.query.file??'');associated.value='';if(nextPath!==path.value){path.value=nextPath;void load();}});
watch(()=>props.branch,()=>directory(''));void load();
function closeFileMenu(event:MouseEvent){if(fileMenu.value&&!fileMenu.value.contains(event.target as Node))fileMenu.value.open=false;}
onMounted(()=>document.addEventListener('click',closeFileMenu));
onBeforeUnmount(()=>{++generation;document.removeEventListener('click',closeFileMenu);});
</script>
<template>
  <div class="file-workbench" :class="{'tree-hidden':!treeVisible}">
    <aside v-if="treeVisible" class="file-sidebar"><div class="file-sidebar-heading"><strong>文件目录</strong><button class="icon-button" aria-label="收起目录" @click="treeVisible=false"><PanelLeftClose :size="16"/></button></div><button class="tree-root" @click="directory('')"><FolderOpen :size="16"/><span>{{String(route.params.repo)}}</span></button><FileTree :key="snapshotRef||branch" :base="base" :branch="snapshotRef||branch" :selected="selected||path" @select="select"/><div class="tree-footer"><GitBranch :size="13"/><span>{{branch}}</span></div></aside>
    <section class="file-main">
      <div class="file-location"><div class="breadcrumbs"><button class="icon-button tree-toggle" :aria-label="treeVisible?'收起文件目录':'展开文件目录'" :aria-pressed="treeVisible" @click="treeVisible=!treeVisible"><FolderOpen :size="17"/></button><button class="root-crumb" @click="directory('')">{{String(route.params.repo)}}</button><template v-for="crumb in breadcrumbs" :key="crumb.path"><ChevronRight :size="14"/><button @click="directory(crumb.path)">{{crumb.name}}</button></template><template v-if="selected"><ChevronRight :size="14"/><strong>{{selected.split('/').pop()}}</strong></template></div><button v-if="selected" class="btn btn-ghost" @click="closePreview"><ArrowLeft :size="14"/>返回目录</button><div v-else class="directory-actions"><button class="icon-button" aria-label="刷新目录" :disabled="loading" @click="load"><RefreshCw :size="15" :class="{spin:loading}"/></button><details ref="fileMenu" class="manage-files" @keydown.esc="fileMenu && (fileMenu.open=false)"><summary class="btn"><Upload :size="15"/>管理文件 <ChevronDown :size="13"/></summary><div class="file-action-menu"><RouterLink :to="workspaceLink('upload')"><Upload :size="15"/><span>上传文件<small>在工作区暂存并提交</small></span></RouterLink><RouterLink :to="workspaceLink('new-file')"><FilePlus2 :size="15"/><span>新建文件<small>创建文本或 JSONL 文件</small></span></RouterLink></div></details></div></div>
      <div v-if="selected" class="preview-split" :class="{'has-associated':associated}"><FilePreview :base="base" :branch="branch" :path="selected" @open="associated=$event"/><FilePreview v-if="associated" :base="base" :branch="branch" :path="associated" compact @close="associated=''" @open="associated=$event"/></div>
      <div v-else-if="loading" class="empty" role="status"><LoaderCircle class="spin" :size="25"/><p>正在读取文件目录…</p></div><div v-else-if="error" class="error-state" role="alert">{{error}}<button class="btn" @click="load">重试</button></div>
      <template v-else>
        <div class="directory-toolbar"><label class="search-field"><Search :size="15"/><input v-model="search" aria-label="搜索当前目录" placeholder="查找文件或文件夹…"/></label><div class="directory-view-controls"><select v-model="sort" aria-label="目录排序"><option value="name">名称</option><option value="updated">最近更新</option><option value="size">文件大小</option></select><div class="segmented" aria-label="目录视图"><button :class="{selected:layout==='list'}" :aria-pressed="layout==='list'" aria-label="列表视图" @click="layout='list'"><List :size="16"/></button><button :class="{selected:layout==='grid'}" :aria-pressed="layout==='grid'" aria-label="网格视图" @click="layout='grid'"><Grid2X2 :size="16"/></button></div></div></div>
        <div v-if="latestCommit" class="directory-commit"><span class="commit-avatar">{{(latestCommit.author||'O').slice(0,1).toUpperCase()||'O'}}</span><strong>{{latestCommit.author||'未知作者'}}</strong><span class="commit-message" :title="latestCommit.message">{{latestCommit.message}}</span><RouterLink :to="commitLink" class="commit-hash">{{latestCommit.id.slice(0,10)}}</RouterLink><span class="commit-date">{{date(latestCommit.timestamp)}}</span><RouterLink :to="historyLink" class="history-action"><History :size="15"/>历史记录</RouterLink></div>
        <div v-if="commitError" class="directory-summary-error"><History :size="14"/><span>提交摘要暂不可用，文件仍可正常浏览。</span><RouterLink :to="historyLink">查看历史</RouterLink></div><div v-if="path" class="parent-directory"><button @click="directory(path.split('/').slice(0,-1).join('/'))"><ArrowLeft :size="13"/>上一级目录</button></div>
        <div v-if="layout==='list'" class="table-scroll directory-table-scroll"><table class="data-table file-table"><thead><tr><th>名称</th><th>最近提交</th><th>大小</th><th>更新时间</th></tr></thead><tbody><tr v-for="node in filtered" :key="node.path"><td><button class="file-name" @click="select(node)"><component :is="icon(node)" :size="18" :class="node.kind==='directory'?'folder-icon':'muted'"/><strong>{{node.name}}</strong><span class="file-extension">{{node.kind==='directory'?'':(node.extension||'').toUpperCase()}}</span></button></td><td class="file-commit" :title="node.lastCommit">{{node.lastCommit||'—'}}</td><td class="mono muted">{{bytes(node.size)}}</td><td class="muted">{{date(node.updatedAt)}}</td></tr></tbody></table></div>
        <div v-else class="file-grid"><button v-for="node in filtered" :key="node.path" class="file-grid-card" @click="select(node)"><component :is="icon(node)" :size="34" :class="node.kind==='directory'?'folder-icon':'muted'"/><strong>{{node.name}}</strong><span>{{node.kind==='directory'?'文件夹':((node.extension||'').toUpperCase()||'文件')+' · '+bytes(node.size)}}</span><small>{{date(node.updatedAt)}}</small></button></div>
        <div v-if="!filtered.length" class="empty directory-empty"><Folder :size="32"/><h3>{{search?'没有匹配的文件':'这个目录还没有文件'}}</h3><p>{{search?'试试其他文件名，或清除当前搜索。':'上传数据文件，开始记录和协作管理你的数据版本。'}}</p><button v-if="search" class="btn" @click="search=''">清除搜索</button><RouterLink v-else :to="workspaceLink('upload')" class="btn btn-primary"><Upload :size="15"/>上传文件</RouterLink></div>
        <div class="file-count"><span>{{nodes.filter(n=>n.kind==='directory').length}} 个文件夹 · {{nodes.filter(n=>n.kind==='file').length}} 个文件</span><span v-if="search">显示 {{filtered.length}} 项</span></div>
        <section v-if="!search&&nodes.some(n=>n.name.toLowerCase()==='readme.md')" class="readme-card"><div><FileText :size="15"/><strong>README.md</strong><span>项目说明</span></div><FilePreview :base="base" :branch="branch" :path="nodes.find(n=>n.name.toLowerCase()==='readme.md')!.path"/></section>
      </template>
    </section>
  </div>
</template>
<style scoped>
