play:flex;gap:11px;padding:11px;border-radius:5px;font-size:13px}.file-action-menu a:hover{background:var(--surface-hover,#303033)}.file-action-menu a>svg{margin-top:2px;color:var(--muted)}.file-action-menu small{display:block;color:var(--muted);font-size:11px;margin-top:3px}.directory-toolbar{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:16px}.directory-toolbar .search-field{width:min(400px,55%)}.directory-view-controls select{background:var(--surface);color:var(--text);font-size:12px;border:1px solid var(--line);border-radius:6px;min-height:34px;padding:4px 10px}.directory-commit{display:flex;align-items:center;gap:10px;min-width:0;padding:13px 16px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--surface-raised);font-size:12px}.commit-avatar{width:25px;height:25px;display:grid;place-items:center;border-radius:50%;background:color-mix(in srgb,var(--primary) 25%,var(--surface));color:var(--text);font-size:11px;font-weight:600;flex-shrink:0}.directory-commit>strong{font-size:12px;font-weight:600;white-space:nowrap}.commit-message{min-width:0;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted)}.commit-hash{font:11px Consolas,monospace;white-space:nowrap;color:var(--muted)}.commit-hash:hover,.history-action:hover{color:var(--text)}.commit-date{color:var(--muted);font-size:11px;white-space:nowrap}.history-action{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted);white-space:nowrap}.directory-table-scroll{overflow:auto}.file-table{width:100%;table-layout:fixed}.file-table th:first-child{width:36%}.file-table th:nth-child(2){width:37%}.file-table th:nth-child(3){width:11%}.file-table th:last-child{width:16%}.file-table th,.file-table td{padding:13px 16px;font-size:12px}.file-table td:last-child{white-space:nowrap}.file-name{display:flex;align-items:center;gap:10px;min-width:0;width:100%;text-align:left;font-size:13px;color:var(--text);padding:0}.file-name strong{font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.file-name:hover strong{text-decoration:underline;text-underline-offset:3px}.file-extension{margin-left:auto;color:var(--muted);font-size:10px;padding-left:12px}.file-commit{color:var(--muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.folder-icon{color:#a998d7}.file-count{display:flex;justify-content:space-between;padding:12px 16px;color:var(--muted);font-size:12px;border-top:1px solid var(--line)}.parent-directory{padding:10px 16px;border-bottom:1px solid var(--line)}.parent-directory button{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted)}.file-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;padding:16px}.file-grid-card{display:flex;align-items:flex-start;flex-direction:column;gap:12px;padding:20px 16px;border:1px solid var(--line);border-radius:6px;min-width:0;min-height:165px;text-align:left;background:var(--surface)}.file-grid-card:hover{background:var(--surface-raised);border-color:var(--primary)}.file-grid-card strong{max-width:100%;overflow:hidden;text-overflow:ellipsis;font-size:13px;font-weight:500}.file-grid-card span,.file-grid-card small{font-size:11px;color:var(--muted)}.file-grid-card small{margin-top:auto}.readme-card{margin:20px 16px;border:1px solid var(--line);border-radius:6px;overflow:hidden}.readme-card>div{display:flex;align-items:center;gap:9px;padding:14px 16px;background:var(--surface-raised);border-bottom:1px solid var(--line);font-size:13px}.readme-card>div>span{margin-left:auto;font-size:11px;color:var(--muted)}.readme-card :deep(.preview-toolbar){display:none}.readme-card :deep(.code-preview){max-height:380px}.preview-split.has-associated{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(280px,1fr)}.preview-split.has-associated>.file-preview+section{border-left:1px solid var(--line)}.directory-empty{border-bottom:1px solid var(--line)}.directory-summary-error{display:flex;align-items:center;gap:8px;padding:12px 16px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);font-size:12px;color:var(--muted)}.directory-summary-error a{margin-left:auto;color:var(--primary-hover)}
